package za.co.loopmanager;
import android.graphics.*;import android.view.View;import java.io.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w393dp-h851dp-xxhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class MonochromeScreenshotTest {
 @Test public void homeHasVerifiedPlanAndReachableNavigation()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().visible().get();za.co.bacy.ui.CustomerHome.Model m=new za.co.bacy.ui.CustomerHome.Model();m.appVersion="0.21.0";m.name="Sample customer";m.monthlyPayment="R300";m.due="8 Dec 2026";m.status="Account connected";m.reference="SAMPLE-REFERENCE";m.paidTotal="R300";m.totalPrice="R1,700";m.balance="R1,400";m.progressPercent=17.65f;m.approvedPayments=1;m.paymentsRemaining="5";m.remaining="30";int[] clicked={-1};a.setContentView(za.co.bacy.ui.CustomerHome.create(a,m,i->clicked[0]=i));View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(1179,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(2553,View.MeasureSpec.EXACTLY));root.layout(0,0,1179,2553);java.util.ArrayList<View> found=new java.util.ArrayList<>();root.findViewsWithText(found,"Payments",View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);View nav=found.stream().filter(v->"Payments".contentEquals(v.getContentDescription())).findFirst().orElseThrow();Rect visible=new Rect();org.junit.Assert.assertTrue(nav.getGlobalVisibleRect(visible));org.junit.Assert.assertEquals(nav.getHeight(),visible.height());java.util.ArrayList<View> readings=new java.util.ArrayList<>();root.findViewsWithText(readings,"R300 paid",View.FIND_VIEWS_WITH_TEXT);org.junit.Assert.assertFalse(readings.isEmpty());org.junit.Assert.assertTrue(readings.get(0).getGlobalVisibleRect(new Rect()));nav.performClick();org.junit.Assert.assertEquals(1,clicked[0]);Bitmap image=Bitmap.createBitmap(1179,2553,Bitmap.Config.ARGB_8888);root.draw(new Canvas(image));File outputFile=new File("build/artifacts/customer-monochrome-home.png");outputFile.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(outputFile)){image.compress(Bitmap.CompressFormat.PNG,100,out);}}
}
